{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Top zip codes by green roof area",
  "width": 400,
  "height": 200,
  "mark": {"type": "bar", "stroke": "black", "color": "green"},
  "encoding": {
    "x": {
      "field": "VEGETATED_SQFT",
      "type": "quantitative",
      "axis": {"title": "Total vegetated roof size (sqft)", "format": ",d"}
    },
    "y": {
      "field": "zip",
      "type": "nominal",
      "sort": "-x",
      "axis": {"title": "Zip code"}
    },
    "tooltip": [
      {"field": "zip", "type": "nominal"},
      {"field": "VEGETATED_SQFT", "type": "quantitative"}
    ]
  }
}
